def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([-5]), fmt([0, 0, 0]), fmt([-1, -2, -3]), fmt([1, -1, 2, -2]),
             fmt([-1, 1, -2, 2]), fmt([3, 2, 1, -1, -2, -3, -4]), fmt([0, -1, 0, -1, 0])]
    for n in (2, 3, 4, 6, 8, 10, 12, 15):
        for _ in range(3):
            tests.append(fmt([rng.randint(-9, 9) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([(-rng.randint(1, 5)) if rng.random() < 0.15 else rng.randint(0, 9) for _ in range(rng.randint(5, 20))]))
    N = 200000
    M = 10 ** 6
    tests.append(fmt([rng.randint(1, M) for _ in range(N // 2)] + [-rng.randint(1, M) for _ in range(N // 2)]))
    tests.append(fmt([rng.randint(-M, M) for _ in range(N)]))
    tests.append(fmt([-rng.randint(1, M) for _ in range(N // 2)] + [rng.randint(0, M) for _ in range(N // 2)]))
    tests.append(fmt([rng.randint(-M, M) for _ in range(5000)]))
    return tests
